// El archivo viene comprimido (.gz); lo marcamos así para que el nodo Compression lo abra
return $input.all().map(item => {
  const b = item.binary?.data;
  if (b) {
    b.fileExtension = 'gz';
    b.mimeType = 'application/gzip';
    b.fileName = 'chunk.json.gz';
  }
  return item;
});

// Empresas con al menos una oferta de ingeniería para Argentina o LATAM
const IS_ENGINEERING = /engineer|engineering|developer|desarrollador|desarrollo|programador|programmer|builder|full.?stack|front.?end|back.?end|ingenier|arquitect|\bsre\b|devops|architect|tech(nical)? lead|l[íi]der t[ée]cnico|forward deployed|machine learning|\bml\b|\bcto\b|head of eng|vp.*eng/i;
const EXCLUDE = /recruit|reclut|talent|sales(?! engineer)|ventas|account exec|marketing|designer|dise[ñn]ador|legal|finance|contador|intern|pasant|practicante|product manager|program manager|project manager|gerente de producto|jefe de producto|\banalyst\b|analista(?! programador)|data scientist|cient[íi]fico de datos|incident manager/i;
// Formularios de banco de talento: dicen "Engineering" pero no hay busqueda detras.
const EXCLUDE_EVERGREEN = /future .*(opportunit|role|position)|general interest|talent (pool|community|network)|open application|spontaneous/i;
const ARGENTINA = /argentin|buenos aires/i;
const LATAM = /latam|latin america|south america|\bamericas\b/i;
// Paises de LATAM, por nombre, por codigo ISO y por ciudad principal.
// Con acentos, porque muchas ofertas escriben "Mexico" o "Peru".
const LATAM_COUNTRY = /\b(argentin|brazil|brasil|colombia|chile|uruguay|per[úu]|paraguay|bolivia|ecuador|venezuela|(?<!new )m[ée]xico|costa rica|panam[áa]|guatemala)\b|\b(ARG|BRA|COL|CHL|URY|PER|MEX|CRI)\b|\b(bogot[áa]|medell[íi]n|barranquilla|cartagena|s[ãa]o paulo|rio de janeiro|porto alegre|belo horizonte|curitiba|florian[óo]polis|joinville|recife|montevideo|asunci[óo]n|guadalajara|monterrey|cdmx|quito|guayaquil|san salvador|tegucigalpa|managua)\b/i;
const REMOTE = /remote|remoto|anywhere|worldwide|global|latam|latin america/i;

// "AR" también es Arkansas: solo cuenta como Argentina si hay otro país de la región
const OTHER_LATAM_CODE = /\b(BR|CO|CL|UY|PE|MX|EC|BO|PY|VE|CR)\b/;
// "Avenue of the Americas" es una calle de Nueva York, no la región
const NY_STREET = /ave(nue)?\.?\s+of\s+(the\s+)?americas/ig;

const SLUG = {
  Ashby: /jobs\.ashbyhq\.com\/([^\/?#]+)/i,
  Greenhouse: /greenhouse\.io\/([^\/?#&]+)/i,
  Lever: /jobs\.lever\.co\/([^\/?#]+)/i,
};
// https://teladoc.wd503.myworkdayjobs.com/teladochealth_is_hiring/job/...
const WORKDAY = /^https?:\/\/([^\/]+\.myworkdayjobs\.com)\/(.+?)\/job\//i;

function esLatam(loc) {
  const l = String(loc || '').replace(NY_STREET, '');
  if (ARGENTINA.test(l) || /\bARG\b/.test(l)) return true;
  if (/\bAR\b/.test(l) && OTHER_LATAM_CODE.test(l)) return true;
  if (LATAM_COUNTRY.test(l)) return true;
  return LATAM.test(l);
}

const companies = {};

for (const item of $input.all()) {
  for (const j of item.json.jobs || []) {
    const url = j.url || '';
    let ats = null, slug = null, careersUrl = '';

    if (j.ats === 'Workday') {
      const m = WORKDAY.exec(url);
      if (!m) continue;
      const host = m[1];
      // el sitio puede venir con prefijo de idioma (en-US): se quita
      const site = m[2].split('/').filter(p => !/^[a-z]{2}(-[A-Za-z]{2})?$/.test(p)).join('/') || m[2];
      ats = 'workday';
      slug = `${host.split('.')[0]}/${site}`;
      careersUrl = `https://${host}/${site}`;
    } else {
      const re = SLUG[j.ats];
      if (!re) continue;
      const m = re.exec(url);
      if (!m || m[1] === 'embed') continue;
      ats = j.ats.toLowerCase();
      slug = m[1];
    }

    const k = `${ats}|${slug.toLowerCase()}`;
    const c = companies[k] ||= {
      ats, slug, company: j.company || slug, careers_url: careersUrl,
      latam_jobs: 0, is_recruiter: false, source: 'aggregator', places: {},
    };

    if (j.is_recruiter) { c.is_recruiter = true; continue; }

    const loc = j.location || '';
    if (loc && !REMOTE.test(loc)) c.places[loc] = (c.places[loc] || 0) + 1;

    const t = j.title || '';
    if (!IS_ENGINEERING.test(t) || EXCLUDE.test(t)) continue;
    if (EXCLUDE_EVERGREEN.test(t)) continue;
    if (esLatam(loc)) c.latam_jobs++;
  }
}

return Object.values(companies)
  .filter(c => c.latam_jobs > 0)
  .map(c => {
    const top = Object.entries(c.places).sort((a, b) => b[1] - a[1])[0];
    delete c.places;
    return { json: { ...c, hq: top ? top[0] : '' } };
  });
